package com.example.app.auth

import android.content.Context
import android.util.Log
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.*
import androidx.core.content.edit
import com.example.app.api.ApiClient

object AuthManager {
    private const val TAG = "AuthManager"
    private const val PREFS = "auth_prefs"
    private const val KEY_TOKEN = "token"
    private const val KEY_TOKEN_TIMESTAMP = "token_timestamp"
    private const val TOKEN_TIMEOUT_MILLIS = 12 * 60 * 60 * 1000L // 12 hours

    private val authState = MutableStateFlow(false)
    private var timeoutJob: Job? = null

    /**
     * Checks if the user is currently logged in with a valid token.
     * Performs automatic logout if token has expired.
     *
     * Senior practice: This method serves as the single source of truth for authentication state,
     * centralizing token validation logic and ensuring consistent behavior across the app.
     *
     * @param context The Android context for accessing SharedPreferences
     * @return true if user is logged in with a valid token, false otherwise
     */
    fun isLoggedIn(context: Context): Boolean {
        val prefs = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
        val token = prefs.getString(KEY_TOKEN, null)
        val timestamp = prefs.getLong(KEY_TOKEN_TIMESTAMP, 0L)
        val now = System.currentTimeMillis()

        if (token != null && now - timestamp < TOKEN_TIMEOUT_MILLIS) {
            // Set bearer token for ApiClient if valid
            ApiClient.setBearerToken(token)
            Log.d(TAG, "User is logged in. Token valid (age: ${now - timestamp}ms)")
            return true
        }

        // If expired, logout (clear token from both places)
        if (token != null && now - timestamp >= TOKEN_TIMEOUT_MILLIS) {
            Log.w(TAG, "Token expired (age: ${now - timestamp}ms >= $TOKEN_TIMEOUT_MILLIS). Performing automatic logout.")
            logout(context)
        }

        Log.d(TAG, "User is not logged in.")
        return false
    }

    fun saveToken(context: Context, token: String) {
        val prefs = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
        prefs.edit {
            putString(KEY_TOKEN, token)
            putLong(KEY_TOKEN_TIMESTAMP, System.currentTimeMillis())
        }
        authState.value = true
        ApiClient.setBearerToken(token)
        startTimeout(context)
        Log.d(TAG, "Token saved successfully (length: ${token.length}, will expire in $TOKEN_TIMEOUT_MILLIS ms)")
    }

    /**
     * Logs out the current user by clearing all authentication data.
     * This is a hard logout - no refresh token attempt.
     *
     * Senior practice: Centralized logout logic ensures consistent cleanup across the app,
     * preventing orphaned sessions or partial logout states.
     *
     * @param context The Android context for accessing SharedPreferences
     */
    fun logout(context: Context) {
        val prefs = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
        prefs.edit {
            remove(KEY_TOKEN)
            remove(KEY_TOKEN_TIMESTAMP)
        }
        com.example.app.session.UserSession.clear()
        authState.value = false
        ApiClient.clearBearerToken()
        timeoutJob?.cancel()
        Log.d(TAG, "User logged out. Token and session cleared.")
    }

    /**
     * Gets the current authentication state as a Flow for reactive updates.
     * Use this for observing auth state changes in ViewModels/Composables.
     *
     * @return Flow that emits true when logged in, false when logged out
     */
    fun getAuthState(): MutableStateFlow<Boolean> = authState

    /**
     * Checks if a 401 response should trigger logout.
     * Used by the HTTP response interceptor to handle unauthorized responses.
     *
     * @param context The Android context
     * @return true if we should perform logout and redirect, false if 401 should be retried/handled elsewhere
     */
    fun handleUnauthorized(context: Context) {
        Log.w(TAG, "Received 401 Unauthorized response. Triggering logout.")
        logout(context)
    }

    // ...existing code...
    fun addAuthStateListener(context: Context, listener: (Boolean) -> Unit) {
        listener(isLoggedIn(context))
    }

    /**
     * Checks if the current token is expired based on timestamp.
     * Useful for pre-flight validation before making API calls.
     *
     * @param context The Android context
     * @return true if token is expired or missing, false if token is still valid
     */
    fun isTokenExpired(context: Context): Boolean {
        val prefs = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
        val timestamp = prefs.getLong(KEY_TOKEN_TIMESTAMP, 0L)
        val now = System.currentTimeMillis()
        val isExpired = now - timestamp >= TOKEN_TIMEOUT_MILLIS
        if (isExpired) {
            Log.d(TAG, "Token is expired (age: ${now - timestamp}ms >= $TOKEN_TIMEOUT_MILLIS)")
        }
        return isExpired
    }

    private fun startTimeout(context: Context) {
        timeoutJob?.cancel()
        timeoutJob = CoroutineScope(Dispatchers.Default).launch {
            val prefs = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
            val timestamp = prefs.getLong(KEY_TOKEN_TIMESTAMP, 0L)
            val now = System.currentTimeMillis()
            val remaining = TOKEN_TIMEOUT_MILLIS - (now - timestamp)
            if (remaining > 0) {
                delay(remaining)
            }
            logout(context)
        }
    }
}

package com.example.app.auth

import android.content.Context
import android.util.Log
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.*
import androidx.core.content.edit
import com.example.app.api.ApiClient

object AuthManager {
    private const val TAG = "AuthManager"
    private const val PREFS = "auth_prefs"
    private const val KEY_TOKEN = "token"
    private const val KEY_TOKEN_TIMESTAMP = "token_timestamp"

    private val authState = MutableStateFlow(false)
    private var timeoutJob: Job? = null

    /**
     * Checks if the user is currently logged in with a valid token.
     * Relies on backend token validation and 401 responses for expiration.
     * Does NOT force logout based on local timeout (unlike old 12-hour logic).
     *
     * Senior practice: This method serves as the single source of truth for authentication state,
     * centralizing token validation logic and ensuring consistent behavior across the app.
     * Now respects backend's token expiration policies rather than forcing arbitrary timeouts.
     *
     * @param context The Android context for accessing SharedPreferences
     * @return true if user is logged in with a valid token, false otherwise
     */
    fun isLoggedIn(context: Context): Boolean {
        // Prefer secure storage when available
        var token: String? = null
        try {
            token = SecureTokenManager.getToken()
        } catch (e: Exception) {
            // fallback to legacy prefs
            val prefs = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
            token = prefs.getString(KEY_TOKEN, null)
        }

        if (token != null) {
            // Set bearer token for ApiClient if valid
            ApiClient.setBearerToken(token)
            Log.d(TAG, "User is logged in. Token present (length: ${token.length})")
            return true
        }

        Log.d(TAG, "User is not logged in.")
        return false
    }

    fun saveToken(context: Context, token: String) {
        // Save to encrypted storage with backend-provided expiration
        // Note: Backend is responsible for token expiration policy
        try {
            // If expiration is known (from backend), use it; otherwise let backend handle it
            SecureTokenManager.saveToken(token, Long.MAX_VALUE) // No local timeout
        } catch (e: Exception) {
            // ignore and fallback to prefs below
        }
        val prefs = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
        prefs.edit {
            putString(KEY_TOKEN, token)
            putLong(KEY_TOKEN_TIMESTAMP, System.currentTimeMillis())
        }
        authState.value = true
        ApiClient.setBearerToken(token)
        Log.d(TAG, "Token saved successfully (length: ${token.length}). Backend handles expiration.")
    }

    /**
     * Logs out the current user by clearing all authentication data.
     * This is a hard logout - no refresh token attempt.
     *
     * Senior practice: Centralized logout logic ensures consistent cleanup across the app,
     * preventing orphaned sessions or partial logout states.
     *
     * @param context The Android context for accessing SharedPreferences
     */
    fun logout(context: Context) {
        // Clear secure storage if available
        try {
            SecureTokenManager.clearToken()
        } catch (e: Exception) {
            // ignore
        }
        val prefs = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
        prefs.edit {
            remove(KEY_TOKEN)
            remove(KEY_TOKEN_TIMESTAMP)
        }
        com.example.app.session.UserSession.clear()
        authState.value = false
        ApiClient.clearBearerToken()
        timeoutJob?.cancel()
        Log.d(TAG, "User logged out. Token and session cleared.")
    }

    /**
     * Gets the current authentication state as a Flow for reactive updates.
     * Use this for observing auth state changes in ViewModels/Composables.
     *
     * @return Flow that emits true when logged in, false when logged out
     */
    fun getAuthState(): MutableStateFlow<Boolean> = authState

    /**
     * Checks if a 401 response should trigger logout.
     * Used by the HTTP response interceptor to handle unauthorized responses.
     *
     * @param context The Android context
     * @return true if we should perform logout and redirect, false if 401 should be retried/handled elsewhere
     */
    fun handleUnauthorized(context: Context) {
        Log.w(TAG, "Received 401 Unauthorized response. Backend indicates session is invalid. Triggering logout.")
        logout(context)
    }

    // ...existing code...
    fun addAuthStateListener(context: Context, listener: (Boolean) -> Unit) {
        listener(isLoggedIn(context))
    }

    /**
     * Checks if the current token is expired based on timestamp.
     * Useful for pre-flight validation before making API calls.
     *
     * Note: This is a legacy method. Expiration is now handled by the backend via 401 responses.
     *
     * @param context The Android context
     * @return true if token is expired or missing, false if token is still valid
     */
    fun isTokenExpired(context: Context): Boolean {
        val prefs = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
        val token = prefs.getString(KEY_TOKEN, null)
        return token == null
    }
}

package com.example.app.auth

import android.content.Context
import android.content.SharedPreferences
import androidx.security.crypto.EncryptedSharedPreferences
import androidx.security.crypto.MasterKey

/**
 * SecureTokenManager - persists auth tokens using EncryptedSharedPreferences backed by Android Keystore.
 * Use SecureTokenManager.initialize(context) once (Application.onCreate) before other calls.
 */
object SecureTokenManager {
    private const val PREFS_NAME = "farmhub_secure_prefs"
    private const val KEY_AUTH_TOKEN = "auth_token"
    private const val KEY_TOKEN_EXPIRES_AT = "token_expires_at"
    private const val KEY_REFRESH_TOKEN = "refresh_token"

    private var prefs: SharedPreferences? = null

    fun initialize(context: Context) {
        if (prefs != null) return
        val masterKey = MasterKey.Builder(context)
            .setKeyScheme(MasterKey.KeyScheme.AES256_GCM)
            .build()

        prefs = EncryptedSharedPreferences.create(
            context,
            PREFS_NAME,
            masterKey,
            EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
            EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM
        )
    }

    private fun requirePrefs(): SharedPreferences {
        return prefs ?: throw IllegalStateException("SecureTokenManager not initialized. Call initialize(context) first.")
    }

    fun saveToken(token: String, expiresAtMillis: Long) {
        requirePrefs().edit().apply {
            putString(KEY_AUTH_TOKEN, token)
            putLong(KEY_TOKEN_EXPIRES_AT, expiresAtMillis)
            apply()
        }
    }

    fun getToken(): String? {
        val p = requirePrefs()
        val token = p.getString(KEY_AUTH_TOKEN, null)
        val expires = p.getLong(KEY_TOKEN_EXPIRES_AT, 0L)
        if (token != null && expires > 0L && System.currentTimeMillis() >= expires) {
            // expired - clear and return null
            clearToken()
            return null
        }
        return token
    }

    fun clearToken() {
        requirePrefs().edit().clear().apply()
    }

    fun saveRefreshToken(refreshToken: String) {
        requirePrefs().edit().putString(KEY_REFRESH_TOKEN, refreshToken).apply()
    }

    fun getRefreshToken(): String? = requirePrefs().getString(KEY_REFRESH_TOKEN, null)
}

package com.example.app.auth

import android.content.Context
import android.util.Log
import com.example.app.api.ApiClient
import com.example.app.session.UserSession

/**
 * SessionRestoration - Handles automatic session restoration on app startup.
 *
 * Responsibilities:
 * - Restore token from secure storage
 * - Restore user session data
 * - Validate restored session
 * - Determine appropriate startup route
 *
 * Senior practice: This centralizes all session restoration logic,
 * ensuring consistent behavior across app lifecycle.
 */
object SessionRestoration {
    private const val TAG = "SessionRestoration"

    /**
     * Restores the user session on app startup.
     * Should be called once in MainActivity.onCreate() before showing UI.
     *
     * @param context Application context
     * @return true if valid session was restored, false otherwise
     */
    fun restoreSessionOnStartup(context: Context): Boolean {
        Log.d(TAG, "Attempting to restore session on app startup...")

        return try {
            // Step 1: Try to load token from secure storage
            val savedToken = SecureTokenManager.getToken()

            if (savedToken.isNullOrBlank()) {
                Log.d(TAG, "No saved token found. User must log in.")
                return false
            }

            // Step 2: Token exists - restore it to ApiClient
            ApiClient.setBearerToken(savedToken)
            Log.d(TAG, "Token restored to ApiClient (length: ${savedToken.length})")

            // Step 3: Restore user session data if available
            restoreUserSessionData(context)

            // Step 4: Validate that we have minimum required session data
            val hasRequiredData = TokenValidator.isSessionValid()

            if (hasRequiredData) {
                Log.d(TAG, "✓ Session successfully restored. User is logged in.")
                return true
            } else {
                Log.w(TAG, "✗ Session restoration incomplete. User session data incomplete.")
                // Token exists but session is incomplete - try to fetch user profile
                // For now, keep token but mark as incomplete
                return true // Token is valid enough for an API call to refresh profile
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error during session restoration: ${e.message}", e)
            false
        }
    }

    /**
     * Restores persisted user session data from local storage.
     * This is in-memory only; used for immediate access without API calls.
     *
     * @param context Application context
     */
    private fun restoreUserSessionData(context: Context) {
        try {
            // For now, session data is only available after successful login
            // In the future, we may persist it to shared preferences for faster restoration
            // For a WhatsApp-like experience, we want to show content immediately with cached data

            val prefs = context.getSharedPreferences("user_session_prefs", Context.MODE_PRIVATE)
            val userId = prefs.getString("user_id", null)
            val userName = prefs.getString("user_name", null)
            val phone = prefs.getString("phone", null)
            val role = prefs.getString("role", null)
            val county = prefs.getString("county", null)
            val subCounty = prefs.getString("sub_county", null)
            val paidUser = prefs.getString("paid_user", null)
            val issued = prefs.getLong("issued", 0L)
            val expires = prefs.getLong("expires", 0L)

            if (!userId.isNullOrBlank()) {
                UserSession.userId = userId
                UserSession.userName = userName
                UserSession.phone = phone
                UserSession.role = role
                UserSession.county = county
                UserSession.subCounty = subCounty
                UserSession.paidUser = paidUser
                UserSession.issued = if (issued > 0) issued else null
                UserSession.expires = if (expires > 0) expires else null

                Log.d(TAG, "User session data restored (userId: $userId, phone: $phone)")
            }
        } catch (e: Exception) {
            Log.w(TAG, "Could not restore user session data: ${e.message}")
            // Continue without session data; will be fetched on next API call
        }
    }

    /**
     * Establishes and persists a complete session after successful login.
     *
     * @param context Application context
     * @param token Authentication token from backend
     * @param userId User ID from login response
     * @param userName User name from login response
     * @param phone User phone from login response
     * @param role User role from login response
     * @param county User county from login response
     * @param subCounty User subcounty from login response
     * @param paidUser Paid user status from login response
     * @param issued Token issued timestamp from backend
     * @param expires Token expiration timestamp from backend
     */
    fun establishSession(
        context: Context,
        token: String,
        userId: String,
        userName: String,
        phone: String,
        role: String? = null,
        county: String? = null,
        subCounty: String? = null,
        paidUser: String? = null,
        issued: Long? = null,
        expires: Long? = null
    ) {
        Log.d(TAG, "Establishing new session (userId: $userId, phone: $phone)")

        try {
            // Save token securely with backend-provided expiration
            val expirationTime = expires ?: (System.currentTimeMillis() + 24 * 60 * 60 * 1000) // Default to 24h if not provided
            SecureTokenManager.saveToken(token, expirationTime)
            ApiClient.setBearerToken(token)

            // Save user session data to preferences for quick restoration
            val prefs = context.getSharedPreferences("user_session_prefs", Context.MODE_PRIVATE)
            prefs.edit().apply {
                putString("user_id", userId)
                putString("user_name", userName)
                putString("phone", phone)
                putString("role", role)
                putString("county", county)
                putString("sub_county", subCounty)
                putString("paid_user", paidUser)
                if (issued != null) putLong("issued", issued)
                if (expires != null) putLong("expires", expires)
                apply()
            }

            // Update in-memory session
            UserSession.token = token
            UserSession.userId = userId
            UserSession.userName = userName
            UserSession.phone = phone
            UserSession.role = role
            UserSession.county = county
            UserSession.subCounty = subCounty
            UserSession.paidUser = paidUser
            UserSession.issued = issued
            UserSession.expires = expires

            // Also save to AuthManager for compatibility
            AuthManager.saveToken(context, token)

            Log.d(TAG, "✓ Session established successfully")
        } catch (e: Exception) {
            Log.e(TAG, "Error establishing session: ${e.message}", e)
            throw e
        }
    }

    /**
     * Destroys the session completely (logout).
     *
     * @param context Application context
     */
    fun destroySession(context: Context) {
        Log.d(TAG, "Destroying session...")

        try {
            // Clear secure storage
            SecureTokenManager.clearToken()

            // Clear shared preferences
            val prefs = context.getSharedPreferences("user_session_prefs", Context.MODE_PRIVATE)
            prefs.edit().clear().apply()

            // Clear auth manager
            AuthManager.logout(context)

            // Clear in-memory session
            UserSession.clear()

            Log.d(TAG, "✓ Session destroyed successfully")
        } catch (e: Exception) {
            Log.e(TAG, "Error destroying session: ${e.message}", e)
        }
    }
}

package com.example.app.features

import android.annotation.SuppressLint
import android.util.Log
import androidx.compose.foundation.layout.padding
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.Modifier
import androidx.navigation.NavHostController
import androidx.navigation.NavType
import androidx.navigation.NavGraph.Companion.findStartDestination
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.currentBackStackEntryAsState
import androidx.navigation.navArgument
import com.example.app.auth.AuthManager
import com.example.app.auth.TokenValidator
import com.example.app.routes.AuthScreen
import com.example.app.routes.IntroScreen
import com.example.app.ui.tabs.HelpScreen
import com.example.app.ui.tabs.ProfileScreen
import com.example.app.ui.tabs.ChatScreen
import com.example.app.ui.tabs.VideoScreen
import com.example.app.ui.components.BottomNavBar
import com.example.app.ui.components.AppHeader
import com.example.app.ui.tabs.VideoDetailScreen

/**
 * Main app navigation with comprehensive authentication enforcement.
 *
 * Senior practice: Centralized navigation logic ensures consistent auth checks
 * across all protected routes. Token validation occurs at navigation composition time
 * with defense-in-depth checks at screen level as well.
 */
@SuppressLint("UnusedMaterialScaffoldPaddingParameter")
@Composable
fun AppNavigation(
    navController: NavHostController,
    onToggleTheme: () -> Unit
) {
    val context = LocalContext.current
    var isLoggedIn by remember { mutableStateOf(AuthManager.isLoggedIn(context)) }

    // Track current route for bottom nav reactively
    val navBackStackEntry by navController.currentBackStackEntryAsState()
    val currentRoute = navBackStackEntry?.destination?.route ?: AppRoutes.INTRO
    val latestCurrentRoute by rememberUpdatedState(currentRoute)

    // Observe auth state changes (e.g., when token expires)
    LaunchedEffect(Unit) {
        AuthManager.addAuthStateListener(context) { loggedIn ->
            Log.d("AppNavigation", "Auth state changed: loggedIn=$loggedIn")
            isLoggedIn = loggedIn
            // If logged out unexpectedly, redirect to auth
            if (!loggedIn && latestCurrentRoute !in listOf(AppRoutes.INTRO, AppRoutes.AUTH)) {
                navController.navigateSingleTopTo(AppRoutes.AUTH) {
                    popUpTo(AppRoutes.INTRO) { inclusive = false }
                }
            }
        }
    }

    NavHost(
        navController = navController,
        startDestination = AppRoutes.INTRO
    ) {
        composable(AppRoutes.INTRO) {
            // Standalone: No header/bottom nav
            IntroScreen(
                onFarmHelpClick = {
                    if (isLoggedIn) navController.navigateToTopLevel(AppRoutes.HELP)
                    else navController.navigateSingleTopTo(AppRoutes.AUTH)
                },
                onVideosClick = {
                    if (isLoggedIn) navController.navigateToTopLevel(AppRoutes.VIDEOS)
                    else navController.navigateSingleTopTo(AppRoutes.AUTH)
                },
            )
        }
        composable(AppRoutes.AUTH) {
            // Standalone: No header/bottom nav
            AuthScreen(
                onLoginSuccess = {
                    Log.d("AppNavigation", "Login successful. Updating auth state.")
                    isLoggedIn = true
                    navController.navigate(AppRoutes.INTRO) {
                        popUpTo(AppRoutes.AUTH) { inclusive = true }
                    }
                },
                onSignupSuccess = {
                    Log.d("AppNavigation", "Signup successful. Returning to login.")
                    navController.navigate(AppRoutes.AUTH) {
                        popUpTo(AppRoutes.AUTH) { inclusive = true }
                    }
                }
            )
        }
        composable(AppRoutes.HELP) {
            AppScaffold(
                navController = navController,
                currentRoute = currentRoute,
                isLoggedIn = isLoggedIn
            ) {
                // Screen-level authentication check (defense-in-depth)
                if (!isLoggedIn) {
                    Log.w("AppNavigation", "Unauthorized access to HELP screen. Redirecting to AUTH.")
                    LaunchedEffect(Unit) {
                        navController.navigateSingleTopTo(AppRoutes.AUTH)
                    }
                    return@AppScaffold
                }

                if (!TokenValidator.isTokenValid()) {
                    Log.w("AppNavigation", "Token invalid for HELP screen. Triggering logout.")
                    AuthManager.logout(context)
                    LaunchedEffect(Unit) {
                        navController.navigateSingleTopTo(AppRoutes.AUTH)
                    }
                    return@AppScaffold
                }

                HelpScreen(
                    onChatClick = {
                        if (isLoggedIn) navController.navigateSingleTopTo(AppRoutes.CHAT)
                        else navController.navigateSingleTopTo(AppRoutes.AUTH)
                    },
                    onVideosClick = {
                        if (isLoggedIn) navController.navigateToTopLevel(AppRoutes.VIDEOS)
                        else navController.navigateSingleTopTo(AppRoutes.AUTH)
                    }
                )
            }
        }
        composable(AppRoutes.PROFILE) {
            AppScaffold(
                navController = navController,
                currentRoute = currentRoute,
                isLoggedIn = isLoggedIn
            ) {
                ProfileScreen(
                    onToggleTheme = onToggleTheme,
                    isLoggedIn = isLoggedIn,
                    onSignInClick = { navController.navigateSingleTopTo(AppRoutes.AUTH) },
                    onSignOutClick = {
                        Log.d("AppNavigation", "User initiated logout from ProfileScreen")
                        AuthManager.logout(context)
                        isLoggedIn = false
                        navController.navigate(AppRoutes.AUTH) {
                            popUpTo(AppRoutes.INTRO) { inclusive = false }
                        }
                    }
                )
            }
        }

        composable(AppRoutes.VIDEOS) {
            AppScaffold(
                navController = navController,
                currentRoute = currentRoute,
                isLoggedIn = isLoggedIn
            ) {
                // Route-level authentication check
                if (!isLoggedIn) {
                    Log.w("AppNavigation", "Unauthorized access to VIDEOS route. Redirecting to AUTH.")
                    LaunchedEffect(Unit) {
                        navController.navigateSingleTopTo(AppRoutes.AUTH)
                    }
                    return@AppScaffold
                }

                // Screen-level authentication check (defense-in-depth)
                if (!TokenValidator.isTokenValid()) {
                    Log.w("AppNavigation", "Token invalid for VIDEOS screen. Triggering logout.")
                    AuthManager.logout(context)
                    LaunchedEffect(Unit) {
                        navController.navigateSingleTopTo(AppRoutes.AUTH)
                    }
                    return@AppScaffold
                }

                VideoScreen(navController = navController)
            }
        }

        composable(
            route = "video_detail/{videoId}",
            arguments = listOf(navArgument("videoId") { type = NavType.IntType })
        ) { backStackEntry ->
            val videoId = backStackEntry.arguments?.getInt("videoId") ?: return@composable
            AppScaffold(
                navController = navController,
                currentRoute = currentRoute,
                isLoggedIn = isLoggedIn
            ) {
                if (!TokenValidator.isTokenValid()) {
                    Log.w("AppNavigation", "Token invalid for VIDEO_DETAIL screen. Redirecting to AUTH.")
                    LaunchedEffect(Unit) {
                        AuthManager.logout(context)
                        navController.navigateSingleTopTo(AppRoutes.AUTH)
                    }
                    return@AppScaffold
                }

                VideoDetailScreen(
                    videoId = videoId,
                    onVideoClick = { nextId ->
                        navController.navigate("video_detail/$nextId")
                    }
                )
            }
        }

        composable(AppRoutes.CHAT) {
            AppScaffold(
                navController = navController,
                currentRoute = currentRoute,
                isLoggedIn = isLoggedIn
            ) {
                // Route-level authentication check
                if (!isLoggedIn) {
                    Log.w("AppNavigation", "Unauthorized access to CHAT route. Redirecting to AUTH.")
                    LaunchedEffect(Unit) {
                        navController.navigateSingleTopTo(AppRoutes.AUTH)
                    }
                    return@AppScaffold
                }

                // Screen-level authentication check (defense-in-depth)
                if (!TokenValidator.isTokenValid()) {
                    Log.w("AppNavigation", "Token invalid for CHAT screen. Triggering logout.")
                    AuthManager.logout(context)
                    LaunchedEffect(Unit) {
                        navController.navigateSingleTopTo(AppRoutes.AUTH)
                    }
                    return@AppScaffold
                }

                ChatScreen(
                    onNavigateBack = {
                        if (!navController.popBackStack()) {
                            navController.navigateToTopLevel(AppRoutes.INTRO)
                        }
                    }
                )
            }
        }
    }
}

@Composable
private fun AppScaffold(
    navController: NavHostController,
    currentRoute: String,
    isLoggedIn: Boolean,
    content: @Composable () -> Unit
) {
    val protectedRoutes = remember { setOf(AppRoutes.HELP, AppRoutes.VIDEOS, AppRoutes.CHAT, AppRoutes.VIDEO_DETAIL) }

    Scaffold(
        topBar = {
            AppHeader(
                title = "FarmHub",
                onChatClick = {
                    if (isLoggedIn) navController.navigateSingleTopTo(AppRoutes.CHAT)
                    else navController.navigateSingleTopTo(AppRoutes.AUTH)
                }
            )
        },
        bottomBar = {
            BottomNavBar(
                currentRoute = currentRoute,
                onTabSelected = { route ->
                    if (route in protectedRoutes && !isLoggedIn) {
                        navController.navigateSingleTopTo(AppRoutes.AUTH)
                        return@BottomNavBar
                    }

                    navController.navigateToTopLevel(route)
                }
            )
        }
    ) { innerPadding ->
        Surface(modifier = Modifier.padding(innerPadding)) {
            content()
        }
    }
}

private fun NavHostController.navigateToTopLevel(route: String) {
    if (currentBackStackEntry?.destination?.route == route) return

    navigate(route) {
        popUpTo(graph.findStartDestination().id) {
            saveState = true
        }
        launchSingleTop = true
        restoreState = true
    }
}

private fun NavHostController.navigateSingleTopTo(route: String) {
    navigateSingleTopTo(route) {}
}

private fun NavHostController.navigateSingleTopTo(
    route: String,
    builder: androidx.navigation.NavOptionsBuilder.() -> Unit
) {
    if (currentBackStackEntry?.destination?.route == route) return

    navigate(route) {
        launchSingleTop = true
        builder()
    }
}

package com.example.app.features

import android.annotation.SuppressLint
import android.util.Log
import androidx.compose.foundation.layout.padding
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.Modifier
import androidx.navigation.NavHostController
import androidx.navigation.NavType
import androidx.navigation.NavGraph.Companion.findStartDestination
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.currentBackStackEntryAsState
import androidx.navigation.navArgument
import com.example.app.auth.AuthManager
import com.example.app.auth.TokenValidator
import com.example.app.auth.SessionRestoration
import com.example.app.routes.AuthScreen
import com.example.app.routes.IntroScreen
import com.example.app.routes.SplashScreen
import com.example.app.ui.tabs.HelpScreen
import com.example.app.ui.tabs.ProfileScreen
import com.example.app.ui.tabs.ChatScreen
import com.example.app.ui.tabs.VideoScreen
import com.example.app.ui.components.BottomNavBar
import com.example.app.ui.components.AppHeader
import com.example.app.ui.tabs.VideoDetailScreen

/**
 * Main app navigation with comprehensive authentication enforcement.
 *
 * Senior practice: Centralized navigation logic ensures consistent auth checks
 * across all protected routes. Token validation occurs at navigation composition time
 * with defense-in-depth checks at screen level as well.
 */
@SuppressLint("UnusedMaterialScaffoldPaddingParameter")
@Composable
fun AppNavigation(
    navController: NavHostController,
    onToggleTheme: () -> Unit
) {
    val context = LocalContext.current
    var isLoggedIn by remember { mutableStateOf(AuthManager.isLoggedIn(context)) }
    var startupCheckComplete by remember { mutableStateOf(false) }
    var startingRoute by remember { mutableStateOf(AppRoutes.SPLASH) }

    // Track current route for bottom nav reactively
    val navBackStackEntry by navController.currentBackStackEntryAsState()
    val currentRoute = navBackStackEntry?.destination?.route ?: startingRoute
    val latestCurrentRoute by rememberUpdatedState(currentRoute)

    // On app startup, determine the correct starting route
    LaunchedEffect(Unit) {
        // This will be called when we navigate away from SPLASH
        startupCheckComplete = true
    }

    // Observe auth state changes (e.g., when token expires via 401)
    LaunchedEffect(Unit) {
        AuthManager.addAuthStateListener(context) { loggedIn ->
            Log.d("AppNavigation", "Auth state changed: loggedIn=$loggedIn")
            isLoggedIn = loggedIn
            // If logged out unexpectedly, redirect to auth
            if (!loggedIn && latestCurrentRoute !in listOf(AppRoutes.INTRO, AppRoutes.AUTH, AppRoutes.SPLASH)) {
                navController.navigateSingleTopTo(AppRoutes.AUTH) {
                    popUpTo(AppRoutes.INTRO) { inclusive = false }
                }
            }
        }
    }

    NavHost(
        navController = navController,
        startDestination = AppRoutes.SPLASH
    ) {
        // SplashScreen handles startup and session restoration
        composable(AppRoutes.SPLASH) {
            SplashScreen(
                onStartupCheckComplete = { restoredLoggedIn ->
                    isLoggedIn = restoredLoggedIn
                    startingRoute = if (restoredLoggedIn) AppRoutes.INTRO else AppRoutes.INTRO

                    // Navigate away from splash to the appropriate screen
                    navController.navigate(startingRoute) {
                        popUpTo(AppRoutes.SPLASH) { inclusive = true }
                    }
                    startupCheckComplete = true
                }
            )
        }

        composable(AppRoutes.INTRO) {
            // Standalone: No header/bottom nav
            IntroScreen(
                onFarmHelpClick = {
                    if (isLoggedIn) navController.navigateToTopLevel(AppRoutes.HELP)
                    else navController.navigateSingleTopTo(AppRoutes.AUTH)
                },
                onVideosClick = {
                    if (isLoggedIn) navController.navigateToTopLevel(AppRoutes.VIDEOS)
                    else navController.navigateSingleTopTo(AppRoutes.AUTH)
                },
            )
        }
        composable(AppRoutes.AUTH) {
            // Standalone: No header/bottom nav
            AuthScreen(
                onLoginSuccess = {
                    Log.d("AppNavigation", "Login successful. Updating auth state.")
                    isLoggedIn = true
                    navController.navigate(AppRoutes.INTRO) {
                        popUpTo(AppRoutes.AUTH) { inclusive = true }
                    }
                },
                onSignupSuccess = {
                    Log.d("AppNavigation", "Signup successful. Returning to login.")
                    navController.navigate(AppRoutes.AUTH) {
                        popUpTo(AppRoutes.AUTH) { inclusive = true }
                    }
                }
            )
        }
        composable(AppRoutes.HELP) {
            AppScaffold(
                navController = navController,
                currentRoute = currentRoute,
                isLoggedIn = isLoggedIn
            ) {
                // Screen-level authentication check (defense-in-depth)
                if (!isLoggedIn) {
                    Log.w("AppNavigation", "Unauthorized access to HELP screen. Redirecting to AUTH.")
                    LaunchedEffect(Unit) {
                        navController.navigateSingleTopTo(AppRoutes.AUTH)
                    }
                    return@AppScaffold
                }

                if (!TokenValidator.isTokenValid()) {
                    Log.w("AppNavigation", "Token invalid for HELP screen. Triggering logout.")
                    AuthManager.logout(context)
                    LaunchedEffect(Unit) {
                        navController.navigateSingleTopTo(AppRoutes.AUTH)
                    }
                    return@AppScaffold
                }

                HelpScreen(
                    onChatClick = {
                        if (isLoggedIn) navController.navigateSingleTopTo(AppRoutes.CHAT)
                        else navController.navigateSingleTopTo(AppRoutes.AUTH)
                    },
                    onVideosClick = {
                        if (isLoggedIn) navController.navigateToTopLevel(AppRoutes.VIDEOS)
                        else navController.navigateSingleTopTo(AppRoutes.AUTH)
                    }
                )
            }
        }
        composable(AppRoutes.PROFILE) {
            AppScaffold(
                navController = navController,
                currentRoute = currentRoute,
                isLoggedIn = isLoggedIn
            ) {
                ProfileScreen(
                    onToggleTheme = onToggleTheme,
                    isLoggedIn = isLoggedIn,
                    onSignInClick = { navController.navigateSingleTopTo(AppRoutes.AUTH) },
                    onSignOutClick = {
                        Log.d("AppNavigation", "User initiated logout from ProfileScreen")
                        AuthManager.logout(context)
                        isLoggedIn = false
                        navController.navigate(AppRoutes.AUTH) {
                            popUpTo(AppRoutes.INTRO) { inclusive = false }
                        }
                    }
                )
            }
        }

        composable(AppRoutes.VIDEOS) {
            AppScaffold(
                navController = navController,
                currentRoute = currentRoute,
                isLoggedIn = isLoggedIn
            ) {
                // Route-level authentication check
                if (!isLoggedIn) {
                    Log.w("AppNavigation", "Unauthorized access to VIDEOS route. Redirecting to AUTH.")
                    LaunchedEffect(Unit) {
                        navController.navigateSingleTopTo(AppRoutes.AUTH)
                    }
                    return@AppScaffold
                }

                // Screen-level authentication check (defense-in-depth)
                if (!TokenValidator.isTokenValid()) {
                    Log.w("AppNavigation", "Token invalid for VIDEOS screen. Triggering logout.")
                    AuthManager.logout(context)
                    LaunchedEffect(Unit) {
                        navController.navigateSingleTopTo(AppRoutes.AUTH)
                    }
                    return@AppScaffold
                }

                VideoScreen(navController = navController)
            }
        }

        composable(
            route = "video_detail/{videoId}",
            arguments = listOf(navArgument("videoId") { type = NavType.IntType })
        ) { backStackEntry ->
            val videoId = backStackEntry.arguments?.getInt("videoId") ?: return@composable
            AppScaffold(
                navController = navController,
                currentRoute = currentRoute,
                isLoggedIn = isLoggedIn
            ) {
                if (!TokenValidator.isTokenValid()) {
                    Log.w("AppNavigation", "Token invalid for VIDEO_DETAIL screen. Redirecting to AUTH.")
                    LaunchedEffect(Unit) {
                        AuthManager.logout(context)
                        navController.navigateSingleTopTo(AppRoutes.AUTH)
                    }
                    return@AppScaffold
                }

                VideoDetailScreen(
                    videoId = videoId,
                    onVideoClick = { nextId ->
                        navController.navigate("video_detail/$nextId")
                    }
                )
            }
        }

        composable(AppRoutes.CHAT) {
            AppScaffold(
                navController = navController,
                currentRoute = currentRoute,
                isLoggedIn = isLoggedIn
            ) {
                // Route-level authentication check
                if (!isLoggedIn) {
                    Log.w("AppNavigation", "Unauthorized access to CHAT route. Redirecting to AUTH.")
                    LaunchedEffect(Unit) {
                        navController.navigateSingleTopTo(AppRoutes.AUTH)
                    }
                    return@AppScaffold
                }

                // Screen-level authentication check (defense-in-depth)
                if (!TokenValidator.isTokenValid()) {
                    Log.w("AppNavigation", "Token invalid for CHAT screen. Triggering logout.")
                    AuthManager.logout(context)
                    LaunchedEffect(Unit) {
                        navController.navigateSingleTopTo(AppRoutes.AUTH)
                    }
                    return@AppScaffold
                }

                ChatScreen(
                    onNavigateBack = {
                        if (!navController.popBackStack()) {
                            navController.navigateToTopLevel(AppRoutes.INTRO)
                        }
                    }
                )
            }
        }
    }
}

@Composable
private fun AppScaffold(
    navController: NavHostController,
    currentRoute: String,
    isLoggedIn: Boolean,
    content: @Composable () -> Unit
) {
    val protectedRoutes = remember { setOf(AppRoutes.HELP, AppRoutes.VIDEOS, AppRoutes.CHAT, AppRoutes.VIDEO_DETAIL) }

    Scaffold(
        topBar = {
            AppHeader(
                title = "FarmHub",
                onChatClick = {
                    if (isLoggedIn) navController.navigateSingleTopTo(AppRoutes.CHAT)
                    else navController.navigateSingleTopTo(AppRoutes.AUTH)
                }
            )
        },
        bottomBar = {
            BottomNavBar(
                currentRoute = currentRoute,
                onTabSelected = { route ->
                    if (route in protectedRoutes && !isLoggedIn) {
                        navController.navigateSingleTopTo(AppRoutes.AUTH)
                        return@BottomNavBar
                    }

                    navController.navigateToTopLevel(route)
                }
            )
        }
    ) { innerPadding ->
        Surface(modifier = Modifier.padding(innerPadding)) {
            content()
        }
    }
}

private fun NavHostController.navigateToTopLevel(route: String) {
    if (currentBackStackEntry?.destination?.route == route) return

    navigate(route) {
        popUpTo(graph.findStartDestination().id) {
            saveState = true
        }
        launchSingleTop = true
        restoreState = true
    }
}

private fun NavHostController.navigateSingleTopTo(route: String) {
    navigateSingleTopTo(route) {}
}

private fun NavHostController.navigateSingleTopTo(
    route: String,
    builder: androidx.navigation.NavOptionsBuilder.() -> Unit
) {
    if (currentBackStackEntry?.destination?.route == route) return

    navigate(route) {
        launchSingleTop = true
        builder()
    }
}

package com.example.app.repository

import com.example.app.api.ApiClient
import com.example.app.models.login.LoginRequest
import com.example.app.models.login.LoginResponse
import com.example.app.session.UserSession
import retrofit2.Call
import retrofit2.Callback
import retrofit2.Response

class LoginRepository {
    fun login(
        phone: String,
        password: String,
        onResult: (LoginResponse?) -> Unit,
        onError: (String) -> Unit
    ) {
        val request = LoginRequest(phone, password)
        try {
            ApiClient.userService.userLogin(request)
                .enqueue(object : Callback<LoginResponse> {
                    override fun onResponse(
                        call: Call<LoginResponse>,
                        response: Response<LoginResponse>
                    ) {
                        try {
                            if (response.isSuccessful && response.body() != null) {
                                val loginResponse = response.body()!!
                                // Store token for Bearer authentication
                                ApiClient.setBearerToken(loginResponse.token)
                                // Store user session data for later use (phone, id, etc.)
                                UserSession.setSessionFromLoginResponse(loginResponse)
                                onResult(loginResponse)
                            } else {
                                onError("Invalid credentials or server error.")
                            }
                        } catch (e: Exception) {
                            onError("Unexpected error: ${e.localizedMessage ?: "Something went wrong."}")
                        }
                    }

                    override fun onFailure(call: Call<LoginResponse>, t: Throwable) {
                        onError("Network error: ${t.localizedMessage ?: "Please check your connection and try again."}")
                    }
                })
        } catch (e: Exception) {
            onError("Unexpected error: ${e.localizedMessage ?: "Something went wrong."}")
        }
    }
}

package com.example.app.repository

import com.example.app.api.ApiClient
import com.example.app.auth.SecureTokenManager
import com.example.app.models.login.LoginRequest
import com.example.app.models.login.LoginResponse
import com.example.app.session.UserSession
import retrofit2.Call
import retrofit2.Callback
import retrofit2.Response

class LoginRepository {
    fun login(
        phone: String,
        password: String,
        onResult: (LoginResponse?) -> Unit,
        onError: (String) -> Unit
    ) {
        val request = LoginRequest(phone, password)
        try {
            ApiClient.userService.userLogin(request)
                .enqueue(object : Callback<LoginResponse> {
                    override fun onResponse(
                        call: Call<LoginResponse>,
                        response: Response<LoginResponse>
                    ) {
                        try {
                            if (response.isSuccessful && response.body() != null) {
                                val loginResponse = response.body()!!
                                // Store token for Bearer authentication
                                ApiClient.setBearerToken(loginResponse.token)
                                // Persist token securely for app restarts
                                try {
                                    SecureTokenManager.saveToken(loginResponse.token, loginResponse.expires)
                                } catch (e: Exception) {
                                    // Don't fail login if persistence fails; ignore and continue
                                }
                                // Store user session data for later use (phone, id, etc.)
                                UserSession.setSessionFromLoginResponse(loginResponse)
                                onResult(loginResponse)
                            } else {
                                onError("Invalid credentials or server error.")
                            }
                        } catch (e: Exception) {
                            onError("Unexpected error: ${e.localizedMessage ?: "Something went wrong."}")
                        }
                    }

                    override fun onFailure(call: Call<LoginResponse>, t: Throwable) {
                        onError("Network error: ${t.localizedMessage ?: "Please check your connection and try again."}")
                    }
                })
        } catch (e: Exception) {
            onError("Unexpected error: ${e.localizedMessage ?: "Something went wrong."}")
        }
    }
}

package com.example.app.repository

import android.content.Context
import android.net.Uri
import android.util.Log
import com.example.app.api.ApiClient
import com.example.app.auth.TokenValidator
import com.example.app.models.message.SendMessageResponse
import com.example.app.models.messaging.ThreadListResponse
import com.example.app.models.messaging.MessagesResponse
import com.example.app.session.UserSession
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import okhttp3.MediaType.Companion.toMediaTypeOrNull
import okhttp3.MultipartBody
import okhttp3.RequestBody.Companion.toRequestBody
import okhttp3.ResponseBody
import retrofit2.Response

/**
 * Repository for messaging endpoints.
 * Enforces token validation before making API calls.
 *
 * Senior practice: Centralized message repository handles all messaging API interactions,
 * including thread listing, message fetching, and sending with validation.
 */
class MessageRepository(private val context: Context) {
    companion object {
        private const val TAG = "MessageRepository"
    }

    private fun normalizePhone(raw: String?): String? {
        if (raw.isNullOrBlank()) return null
        val trimmed = raw.trim()
        return when {
            trimmed.startsWith("+254") -> trimmed
            trimmed.startsWith("0") && trimmed.length == 10 -> "+254" + trimmed.drop(1)
            else -> trimmed
        }
    }

    suspend fun sendMessage(
        message: String,
        attachmentUri: Uri?,
        recipientPhone: String?
    ): Response<SendMessageResponse> = withContext(Dispatchers.IO) {
        // Pre-flight token validation
        if (!TokenValidator.isTokenValid()) {
            Log.w(TAG, "Cannot send message: token invalid or missing. Aborting request.")
            return@withContext Response.error(
                401,
                ResponseBody.create("text/plain".toMediaTypeOrNull(), "No valid authentication token")
            )
        }

        val currentUserPhone = UserSession.phone
        val normalizedRecipient = normalizePhone(recipientPhone)
        if (normalizedRecipient == null && currentUserPhone.isNullOrBlank()) {
            Log.e(
                TAG,
                "Aborting send: no recipientPhone provided and current user phone missing. tokenPresent=${ApiClient.currentToken()!=null}"
            )
            return@withContext Response.error(400, ResponseBody.create("text/plain".toMediaTypeOrNull(), "No recipient available"))
        }
        val messageBody = message.toRequestBody("text/plain".toMediaTypeOrNull())
        val targetPhone = normalizedRecipient ?: currentUserPhone!!.trim()
        val phoneBody = targetPhone.toRequestBody("text/plain".toMediaTypeOrNull())

        val attachmentPart = attachmentUri?.let { uri ->
            try {
                context.contentResolver.openInputStream(uri)?.use { inputStream ->
                    val bytes = inputStream.readBytes()
                    val requestFile = bytes.toRequestBody("image/*".toMediaTypeOrNull(), 0, bytes.size)
                    MultipartBody.Part.createFormData(
                        "attachment",
                        "image.jpg",
                        requestFile
                    )
                }
            } catch (e: Exception) {
                Log.e(TAG, "Attachment read failed: ${e.message}")
                null
            }
        }
        val start = System.currentTimeMillis()
        Log.d(
            TAG,
            "POST /messaging recipient=$targetPhone msgSize=${message.length} attachment=${attachmentPart!=null} tokenPresent=${ApiClient.currentToken()!=null} userPhone=$currentUserPhone"
        )
        val resp = try {
            ApiClient.userService.sendMessageWithAttachment(
                messageBody,
                phoneBody,
                attachmentPart
            ).execute()
        } catch (e: Exception) {
            Log.e(TAG, "Network exception sending message: ${e.message}")
            return@withContext Response.error(500, ResponseBody.create("text/plain".toMediaTypeOrNull(), e.message ?: "Network error"))
        }
        val took = System.currentTimeMillis() - start
        if (!resp.isSuccessful) {
            try { Log.e(TAG, "SendMessage failed code=${resp.code()} body=${resp.errorBody()?.string()} took=${took}ms") } catch (_: Exception) {}
        } else {
            val body = resp.body()
            Log.d(TAG, "SendMessage success code=${resp.code()} took=${took}ms status=${body?.status}")
        }
        resp
    }

    /**
     * Fetches all conversation threads for the current user.
     * Enforces token validation before making the request.
     *
     * @return Response containing ThreadListResponse on success
     */
    suspend fun getThreads(): Response<ThreadListResponse> = withContext(Dispatchers.IO) {
        if (!TokenValidator.isTokenValid()) {
            Log.w(TAG, "Cannot fetch threads: token invalid or missing. Aborting request.")
            return@withContext Response.error(
                401,
                ResponseBody.create("text/plain".toMediaTypeOrNull(), "No valid authentication token")
            )
        }

        Log.d(TAG, "GET /messaging (threads) tokenPresent=true, initiating request...")
        val resp = ApiClient.userService.getThreads().execute()
        if (!resp.isSuccessful) {
            try { Log.e(TAG, "Threads fetch failed code=${resp.code()} body=${resp.errorBody()?.string()}") } catch (_: Exception) {}
        } else {
            Log.d(TAG, "Threads fetch success. Count=${resp.body()?.threads?.size ?: 0}")
        }
        resp
    }

    /**
     * Fetches messages in a specific thread with the given recipient.
     * Enforces token validation before making the request.
     *
     * @param threadRecipientId The recipient ID for the thread
     * @return Response containing MessagesResponse on success
     */
    suspend fun getMessages(threadRecipientId: String): Response<MessagesResponse> = withContext(Dispatchers.IO) {
        if (!TokenValidator.isTokenValid()) {
            Log.w(TAG, "Cannot fetch messages: token invalid or missing. Aborting request.")
            return@withContext Response.error(
                401,
                ResponseBody.create("text/plain".toMediaTypeOrNull(), "No valid authentication token")
            )
        }

        Log.d(TAG, "GET /messaging/$threadRecipientId tokenPresent=true, initiating request...")
        val resp = ApiClient.userService.getMessages(threadRecipientId).execute()
        if (!resp.isSuccessful) {
            try { Log.e(TAG, "Messages fetch failed code=${resp.code()} body=${resp.errorBody()?.string()}") } catch (_: Exception) {}
        } else {
            Log.d(TAG, "Messages fetch success. Count=${resp.body()?.messages?.size ?: 0}")
        }
        resp
    }
}

package com.example.app.repository

import android.content.Context
import android.net.Uri
import android.util.Log
import com.example.app.api.ApiClient
import com.example.app.auth.TokenValidator
import com.example.app.models.message.SendMessageResponse
import com.example.app.models.messaging.ThreadListResponse
import com.example.app.models.messaging.MessagesResponse
import com.example.app.models.messaging.UserProfileCache
import com.example.app.session.UserSession
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import okhttp3.MediaType.Companion.toMediaTypeOrNull
import okhttp3.MultipartBody
import okhttp3.RequestBody.Companion.toRequestBody
import okhttp3.ResponseBody
import retrofit2.Response

/**
 * Repository for messaging endpoints.
 * Enforces token validation before making API calls.
 *
 * Senior practice: Centralized message repository handles all messaging API interactions,
 * including thread listing, message fetching, and sending with validation.
 */
class MessageRepository(private val context: Context) {
    companion object {
        private const val TAG = "MessageRepository"
    }

    // User name cache. Key: phone number, Value: user's full name
    private val userNameCache = mutableMapOf<String, UserProfileCache>()

    private fun normalizePhone(raw: String?): String? {
        if (raw.isNullOrBlank()) return null
        val trimmed = raw.trim()
        return when {
            trimmed.startsWith("+254") -> trimmed
            trimmed.startsWith("0") && trimmed.length == 10 -> "+254" + trimmed.drop(1)
            else -> trimmed
        }
    }

    suspend fun sendMessage(
        message: String,
        attachmentUri: Uri?,
        recipientPhone: String?
    ): Response<SendMessageResponse> = withContext(Dispatchers.IO) {
        // Pre-flight token validation
        if (!TokenValidator.isTokenValid()) {
            Log.w(TAG, "Cannot send message: token invalid or missing. Aborting request.")
            return@withContext Response.error(
                401,
                ResponseBody.create("text/plain".toMediaTypeOrNull(), "No valid authentication token")
            )
        }

        val currentUserPhone = UserSession.phone
        val normalizedRecipient = normalizePhone(recipientPhone)
        if (normalizedRecipient == null && currentUserPhone.isNullOrBlank()) {
            Log.e(
                TAG,
                "Aborting send: no recipientPhone provided and current user phone missing. tokenPresent=${ApiClient.currentToken()!=null}"
            )
            return@withContext Response.error(400, ResponseBody.create("text/plain".toMediaTypeOrNull(), "No recipient available"))
        }
        val messageBody = message.toRequestBody("text/plain".toMediaTypeOrNull())
        val targetPhone = normalizedRecipient ?: currentUserPhone!!.trim()
        val phoneBody = targetPhone.toRequestBody("text/plain".toMediaTypeOrNull())

        val attachmentPart = attachmentUri?.let { uri ->
            try {
                context.contentResolver.openInputStream(uri)?.use { inputStream ->
                    val bytes = inputStream.readBytes()
                    val requestFile = bytes.toRequestBody("image/*".toMediaTypeOrNull(), 0, bytes.size)
                    MultipartBody.Part.createFormData(
                        "attachment",
                        "image.jpg",
                        requestFile
                    )
                }
            } catch (e: Exception) {
                Log.e(TAG, "Attachment read failed: ${e.message}")
                null
            }
        }
        val start = System.currentTimeMillis()
        Log.d(
            TAG,
            "POST /messaging recipient=$targetPhone msgSize=${message.length} attachment=${attachmentPart!=null} tokenPresent=${ApiClient.currentToken()!=null} userPhone=$currentUserPhone"
        )
        val resp = try {
            ApiClient.userService.sendMessageWithAttachment(
                messageBody,
                phoneBody,
                attachmentPart
            ).execute()
        } catch (e: Exception) {
            Log.e(TAG, "Network exception sending message: ${e.message}")
            return@withContext Response.error(500, ResponseBody.create("text/plain".toMediaTypeOrNull(), e.message ?: "Network error"))
        }
        val took = System.currentTimeMillis() - start
        if (!resp.isSuccessful) {
            try { Log.e(TAG, "SendMessage failed code=${resp.code()} body=${resp.errorBody()?.string()} took=${took}ms") } catch (_: Exception) {}
        } else {
            val body = resp.body()
            Log.d(TAG, "SendMessage success code=${resp.code()} took=${took}ms status=${body?.status}")
        }
        resp
    }

    /**
     * Fetches all conversation threads for the current user.
     * Enforces token validation before making the request.
     *
     * @return Response containing ThreadListResponse on success
     */
    suspend fun getThreads(): Response<ThreadListResponse> = withContext(Dispatchers.IO) {
        if (!TokenValidator.isTokenValid()) {
            Log.w(TAG, "Cannot fetch threads: token invalid or missing. Aborting request.")
            return@withContext Response.error(
                401,
                ResponseBody.create("text/plain".toMediaTypeOrNull(), "No valid authentication token")
            )
        }

        Log.d(TAG, "GET /messaging (threads) tokenPresent=true, initiating request...")
        val resp = ApiClient.userService.getThreads().execute()
        if (!resp.isSuccessful) {
            try { Log.e(TAG, "Threads fetch failed code=${resp.code()} body=${resp.errorBody()?.string()}") } catch (_: Exception) {}
        } else {
            Log.d(TAG, "Threads fetch success. Count=${resp.body()?.threads?.size ?: 0}")
        }
        resp
    }

    /**
     * Fetches messages in a specific thread with the given recipient.
     * Enforces token validation before making the request.
     *
     * @param threadRecipientId The recipient ID for the thread
     * @return Response containing MessagesResponse on success
     */
    suspend fun getMessages(threadRecipientId: String): Response<MessagesResponse> = withContext(Dispatchers.IO) {
        if (!TokenValidator.isTokenValid()) {
            Log.w(TAG, "Cannot fetch messages: token invalid or missing. Aborting request.")
            return@withContext Response.error(
                401,
                ResponseBody.create("text/plain".toMediaTypeOrNull(), "No valid authentication token")
            )
        }

        Log.d(TAG, "GET /messaging/$threadRecipientId tokenPresent=true, initiating request...")
        val resp = ApiClient.userService.getMessages(threadRecipientId).execute()
        if (!resp.isSuccessful) {
            try { Log.e(TAG, "Messages fetch failed code=${resp.code()} body=${resp.errorBody()?.string()}") } catch (_: Exception) {}
        } else {
            Log.d(TAG, "Messages fetch success. Count=${resp.body()?.messages?.size ?: 0}")
        }
        resp
    }

    /**
     * Fetches user profile information to map phone numbers to user names.
     * Uses in-memory cache to reduce API calls.
     *
     * @param phone The phone number to look up
     * @return User's full name or phone if unavailable
     */
    suspend fun getUserNameByPhone(phone: String?): String = withContext(Dispatchers.IO) {
        if (phone.isNullOrBlank()) return@withContext "Unknown User"

        // Check cache first
        val cached = userNameCache[phone]
        if (cached != null && !cached.isExpired()) {
            Log.d(TAG, "Returning cached name for $phone")
            return@withContext cached.name
        }

        // For current user, use session data
        if (phone == UserSession.phone) {
            val displayName = UserSession.userName.takeIf { !it.isNullOrBlank() } ?: phone
            userNameCache[phone] = UserProfileCache(phone, displayName)
            return@withContext displayName
        }

        // Try to fetch from API (optional - if endpoint supports it)
        // For now, we fall back to returning the phone as no dedicated endpoint exists
        val displayName = phone.takeIf { it.isNotBlank() } ?: "Unknown User"
        userNameCache[phone] = UserProfileCache(phone, displayName)
        Log.d(TAG, "Generated fallback name for $phone")
        displayName
    }

    fun clearUserNameCache() {
        userNameCache.clear()
        Log.d(TAG, "User name cache cleared")
    }
}

package com.example.app.routes

import android.util.Patterns
